MultiLanguageItemData['tw'][192753] = {name = "憤怒的鱗片", additional_info = "任務物品\n[q]\"對守護巨龍及他們的泰坦盟友施加的命令做出的殘酷又尖銳的反駁。由一頭元龍的觀點講述，在被逼到龍族社會的邊緣後，他最終被逼得不得不造反。\""}
MultiLanguageItemData['tw'][192754] = {name = "龍吉訶德", additional_info = "任務物品\n[q]\"遠古巨龍再也無法區分他的夢境以及清醒世界的故事。在長期受難的龍裔的陪伴下，龍吉訶德踏上一趟奇妙的旅途，要復興想像中的黃金年代。\""}
MultiLanguageItemData['tw'][192755] = {name = "魔翼", additional_info = "任務物品\n[q]\"一群堅毅的龍獸和大膽的幼龍集結起來摧毀一個具有恐怖力量的神器，只有創造出它的瘋狂守護巨龍的熔爐才有辦法毀滅它。\""}
MultiLanguageItemData['tw'][192756] = {name = "紅龍軍團與黑龍軍團", additional_info = "任務物品\n[q]\"出身低微的黑龍無法在他的軍國主義出身及他對聰明與才智的尊重中取得平衡，最終因為單戀及猖獗於龍類之間的物質主義陷入絕望。\""}
MultiLanguageItemData['tw'][192757] = {name = "傲慢與元龍", additional_info = "任務物品\n[q]\"典型的愛情故事。背景在守護巨龍以前的年代，嶄露頭角的年輕元龍挺身違抗傲慢的長老。隨著他們互相了解，他們的敵意轉變為欣賞，最後則演變成愛。\""}
MultiLanguageItemData['tw'][192758] = {name = "沉重繩索", additional_info = "任務物品\n[q]\"被龍人定義為沉重。你只要使用一綑線圈應該就能夠拖走巨石。\""}
